RWStructuredBuffer<float> Output : register(u0);
[RootSignature("UAV(u0)")]
[numthreads(8, 8, 1)]
void main(uint3 id : SV_DispatchThreadID)
{
    float sum = 0;
    for (int i = 0; i < 4; i++) sum += sin(id.x * i) * cos(id.y + i);
#ifdef HEAVY
    for (int j = 0; j < 16; j++) sum += sqrt(abs(sum) + j);
#endif
    Output[id.x] = sum;
}
